import{describe,it,expect}from"vitest";import{STATE_ADJACENCY_MAP,calculatePartialCredit,generateQuestionOptions,verifyBorderSymmetry,summarizeQuizPerformance}from"../../frontend/border-neighbors-quiz/border-neighbors-quiz.js";describe("Border Neighbors Dataset Integrity",()=>{it("covers at least 10 states at launch (contains 29 states)",()=>{const e=Object.keys(STATE_ADJACENCY_MAP);expect(e.length).toBeGreaterThanOrEqual(10),expect(e.length).toBe(29)}),it("every state has required fields (id, name, capital, region, neighbors)",()=>{Object.keys(STATE_ADJACENCY_MAP).forEach(e=>{const t=STATE_ADJACENCY_MAP[e];expect(t).toHaveProperty("id"),expect(t).toHaveProperty("name"),expect(t).toHaveProperty("capital"),expect(t).toHaveProperty("region"),expect(t).toHaveProperty("neighbors"),expect(typeof t.id).toBe("string"),expect(typeof t.name).toBe("string"),expect(typeof t.capital).toBe("string"),expect(typeof t.region).toBe("string"),expect(Array.isArray(t.neighbors)).toBe(!0),expect(t.neighbors.length).toBeGreaterThan(0)})}),it("verifies complete land border symmetry across all states",()=>{const e=verifyBorderSymmetry(STATE_ADJACENCY_MAP);expect(e.isValid).toBe(!0),expect(e.errors).toEqual([])})}),describe("Partial-Credit Scoring Logic",()=>{it("returns 100% score and isPerfect true for perfect selection",()=>{const e=calculatePartialCredit("MH",["GJ","MP","CT","TS","KA","GA"]);expect(e.scorePercentage).toBe(100),expect(e.earnedPoints).toBe(100),expect(e.isPerfect).toBe(!0),expect(e.tp.length).toBe(6),expect(e.fp.length).toBe(0),expect(e.fn.length).toBe(0)}),it("awards partial credit when some correct neighbors are selected without false choices",()=>{const e=calculatePartialCredit("RJ",["PB","HR","UP","MP"]);expect(e.scorePercentage).toBe(80),expect(e.earnedPoints).toBe(80),expect(e.isPerfect).toBe(!1),expect(e.tp.length).toBe(4),expect(e.fn.length).toBe(1),expect(e.fn).toContain("GJ")}),it("applies penalty for false positive choices",()=>{const e=calculatePartialCredit("GA",["MH","KA","TN"]);expect(e.scorePercentage).toBe(75),expect(e.tp.length).toBe(2),expect(e.fp.length).toBe(1),expect(e.fp).toContain("TN"),expect(e.isPerfect).toBe(!1)}),it("floors score at 0% for excessive wrong choices",()=>{const e=calculatePartialCredit("KL",["UP","MP","RJ","GJ"]);expect(e.scorePercentage).toBe(0),expect(e.earnedPoints).toBe(0),expect(e.tp.length).toBe(0),expect(e.fp.length).toBe(4)}),it("handles empty selection gracefully",()=>{const e=calculatePartialCredit("TN",[]);expect(e.scorePercentage).toBe(0),expect(e.earnedPoints).toBe(0),expect(e.tp.length).toBe(0),expect(e.fn.length).toBe(3)}),it("handles invalid or missing target state ID",()=>{const e=calculatePartialCredit(null,["MH"]);expect(e.scorePercentage).toBe(0),expect(e.targetStateName).toBe("Unknown");const t=calculatePartialCredit("INVALID",["MH"]);expect(t.scorePercentage).toBe(0)})}),describe("Question Options Generator",()=>{it("includes all actual neighbors in the options list",()=>{const e=generateQuestionOptions("UP",8),t=STATE_ADJACENCY_MAP.UP.neighbors,r=e.map(e=>e.id);t.forEach(e=>{expect(r).toContain(e)})}),it("flags correctly whether each option is a neighbor or distractor",()=>{const e=generateQuestionOptions("GJ",8),t=new Set(STATE_ADJACENCY_MAP.GJ.neighbors);e.forEach(e=>{t.has(e.id)?expect(e.isNeighbor).toBe(!0):expect(e.isNeighbor).toBe(!1)})}),it("returns empty array for invalid state ID",()=>{const e=generateQuestionOptions("INVALID_STATE");expect(e).toEqual([])})}),describe("Quiz Performance Summarizer",()=>{it("calculates average score, total points, grade, and badge correctly",()=>{const e=[calculatePartialCredit("MH",["GJ","MP","CT","TS","KA","GA"]),calculatePartialCredit("GA",["MH","KA"]),calculatePartialCredit("KL",["KA"]),calculatePartialCredit("TN",["KL","KA","AP"])],t=summarizeQuizPerformance(e);expect(t.totalQuestions).toBe(4),expect(t.averageScore).toBe(88),expect(t.totalEarnedPoints).toBe(350),expect(t.totalPossiblePoints).toBe(400),expect(t.perfectQuestions).toBe(3),expect(t.grade).toBe("A"),expect(t.badge).toBe("Cartography Whiz")}),it("handles empty results array gracefully",()=>{const e=summarizeQuizPerformance([]);expect(e.totalQuestions).toBe(0),expect(e.averageScore).toBe(0),expect(e.grade).toBe("N/A"),expect(e.badge).toBe("Novice Traveler")})});